SELECT timer.id, timer.ticket_id, timer.timer_type, timer.deadline FROM sla_timer timer INNER JOIN ( SELECT ticket_id, MAX(id) AS latest_id FROM sla_timer WHERE deleted = 0 AND UPPER(TRIM(timer_type)) = 'RESOLVE' AND deadline IS NOT NULL AND ticket_id IN
#{tid}
GROUP BY ticket_id ) latest ON latest.latest_id = timer.id WHERE timer.deleted = 0
